BINDINGS = (
    "effective_scientific_and_execution_config_sha256", "source_revision_and_source_files_sha256",
    "topology_and_module_initialization_spec_sha256", "source_weight_file_and_loaded_state_sha256",
    "common_encoder_and_diagnostic_head_initial_state_sha256", "train_validation_cohort_identity_label_order_sha256",
    "source_image_and_supervision_input_bindings_sha256", "transform_contract_and_implementation_sha256",
    "optimizer_groups_and_rates_schedule_sha256", "objective_coefficients_and_reductions_sha256",
    "rng_streams_seeds_shuffle_augmentation_sha256", "runtime_hardware_precision_determinism_sha256",
    "stopping_checkpoint_selection_metric_definition_sha256",
)
ADMIN = {"screen_or_repeat_phase_label", "review_timestamp", "analysis_role_alias"}
KEYS = {"run_id", "model_id", "protocol_version", "initialization", "objective", "seed", "recipe", "bindings"}


def digest(raw):
    return hashlib.sha256(raw).hexdigest()


def canonical(value):
    return json.dumps(value, sort_keys=True, separators=(",", ":"), allow_nan=False).encode()


def _hash(value):
    return isinstance(value, str) and re.fullmatch(r"[0-9a-f]{64}", value) is not None


def _json(raw):
    if type(raw) is not bytes or len(raw) > 1048576:
        raise ValueError("bounded raw JSON bytes required")
    def pairs(items):
        result = {}
        for key, value in items:
            if key in result:
                raise ValueError("duplicate JSON key")
            result[key] = value
        return result
    return json.loads(raw, object_pairs_hook=pairs,
                      parse_constant=lambda _: (_ for _ in ()).throw(ValueError("nonfinite JSON")))


def scientific_contract(record):
    if type(record) is not dict or set(record) not in (KEYS, KEYS | {"administrative"}):
        raise ValueError("missing or unclassified execution fields")
    if (record["model_id"] != MODEL_ID or type(record["protocol_version"]) is not int
            or record["protocol_version"] != 2 or record["recipe"] != "A"
            or type(record["seed"]) is not int or record["seed"] not in (42, 43, 44)
            or record["initialization"] not in ("RANDOM", "IMAGENET", "RADIMAGENET")
            or record["objective"] not in ("HARD", "LEGACY", "SHARED-010", "SEPARATE-010")
            or not isinstance(record["run_id"], str) or not record["run_id"]):
        raise ValueError("unreviewed run identity")
    bindings = record["bindings"]
    if type(bindings) is not dict or set(bindings) != set(BINDINGS) or not all(_hash(x) for x in bindings.values()):
        raise ValueError("complete exact execution/input digests required")
    admin = record.get("administrative", {})
    if type(admin) is not dict or not set(admin) <= ADMIN or not all(isinstance(x, str) for x in admin.values()):
        raise ValueError("unreviewed administrative exclusion")
    return {k: record[k] for k in sorted(KEYS)}


def require_exact_reuse(previous, requested, *, completion_bytes, completion_sha256,
                       manifest_bytes, verified_output_hashes):
    """Validate a supplied receipt and freshly verified artifact digest map.

    The caller must obtain completion_sha256 from its trusted run ledger and
    rehash actual output bytes before supplying verified_output_hashes. This pure
    validator does not claim those reads occurred and never grants execution.
    """
    old, new = scientific_contract(previous), scientific_contract(requested)
    if old != new:
        raise ValueError("run reuse rejected: execution or input binding mismatch")
    if not _hash(completion_sha256) or digest(completion_bytes) != completion_sha256:
        raise ValueError("completion receipt hash mismatch")
    receipt = _json(completion_bytes)
    if (type(receipt) is not dict or receipt.get("status") != "complete"
            or receipt.get("run_id") != old["run_id"]
            or receipt.get("contract_sha256") != digest(canonical(old))
            or receipt.get("output_manifest_sha256") != digest(manifest_bytes)):
        raise ValueError("incomplete or unbound run receipt")
    manifest = _json(manifest_bytes)
    outputs = manifest.get("files") if type(manifest) is dict else None
    if (type(outputs) is not dict or not outputs
            or not all(isinstance(k, str) and k and _hash(v) for k, v in outputs.items())
            or type(verified_output_hashes) is not dict or outputs != verified_output_hashes):
        raise ValueError("fresh output-manifest verification required")
    return {"run_id": old["run_id"], "reuse_compatible": True,
            "counts_as_additional_run": False, "pilot_execution_authorized": False}

"""CPU-only initialization scopes and private data-order/augmentation streams."""
from contextlib import contextmanager
import hashlib
import random
import threading

STREAMS = (
    "encoder_initialization", "diagnostic_head_initialization",
    "auxiliary_head_initialization", "shuffle", "augmentation",
    "shared_fusion_initialization",
)
_CONSTRUCTION_LOCK = threading.RLock()


def stream_seed(seed: int, stream: str) -> int:
    if type(seed) is not int or seed not in (42, 43, 44) or stream not in STREAMS:
        raise ValueError("unreviewed seed or RNG stream")
    raw = f"performance-v2-rng-v1|{seed}|{stream}".encode("utf-8")
    return int.from_bytes(hashlib.sha256(raw).digest()[:8], "big") % (2**32)


def private_random(seed: int, stream: str) -> random.Random:
    """No mutation of Python's global RNG; caller owns this stream's lifetime."""
    return random.Random(stream_seed(seed, stream))


def cpu_generator(seed: int, stream: str):
    import torch
    return torch.Generator(device="cpu").manual_seed(stream_seed(seed, stream))


@contextmanager
def initialization_scope(seed: int, stream: str):
    """Restore CPU RNG after construction; never seed or inspect CUDA devices.

    Construction is serialized among these scopes. Other application threads must
    not consume the global torch CPU generator during construction.
    """
    import torch
    value = stream_seed(seed, stream)
    if torch.get_default_dtype() != torch.float32:
        raise ValueError("construction requires explicit float32 default")
    with _CONSTRUCTION_LOCK, torch.random.fork_rng(devices=[]), torch.device("cpu"):
        torch.random.default_generator.manual_seed(value)
        yield

"""Pure validation-only selection. No checkpoint file loading or metric I/O."""
from dataclasses import dataclass
import math

OBJECTIVE_ORDER = ("HARD", "LEGACY", "SHARED-010", "SEPARATE-010")
INITIALIZATION_ORDER = ("RANDOM-A", "IMAGENET-A", "RADIMAGENET-A")


@dataclass(frozen=True)
class ValidationEpoch:
    epoch: int
    macro_f1: float
    diagnostic_ce: float
    split: str = "validation"

    def __post_init__(self):
        if self.split != "validation":
            raise ValueError("only validation records may select checkpoints")
        if type(self.epoch) is not int or not 1 <= self.epoch <= 100:
            raise ValueError("invalid epoch")
        if (isinstance(self.macro_f1, bool) or not math.isfinite(self.macro_f1)
                or not 0 <= self.macro_f1 <= 1 or isinstance(self.diagnostic_ce, bool)
                or not math.isfinite(self.diagnostic_ce) or self.diagnostic_ce < 0):
            raise ValueError("invalid diagnostic validation metrics")


def select_checkpoint(history):
    records = list(history)
    if not records or any(type(r) is not ValidationEpoch for r in records):
        raise ValueError("typed validation history required")
    if len({r.epoch for r in records}) != len(records):
        raise ValueError("duplicate epoch")
    maximum = max(r.macro_f1 for r in records)
    candidates = [r for r in records if maximum - r.macro_f1 <= 1e-12]
    return min(candidates, key=lambda r: (r.diagnostic_ce, r.epoch))


class ValidationPatience:
    """Raw min-delta counter, independent of tolerance-ranked checkpoint choice."""
    def __init__(self):
        self.last_epoch = 0
        self.best = -math.inf
        self.without_improvement = 0
        self.stopped = False

    def observe(self, record):
        if (type(record) is not ValidationEpoch or self.stopped
                or record.epoch != self.last_epoch + 1):
            raise ValueError("sequential validation epochs required before stopping")
        self.last_epoch = record.epoch
        if record.macro_f1 > self.best + 1e-4:
            self.best = record.macro_f1
            self.without_improvement = 0
        else:
            self.without_improvement += 1
        self.stopped = (record.epoch == 100 or
                        (record.epoch >= 20 and self.without_improvement >= 15))
        return self.stopped


@dataclass(frozen=True)
class SeedValidation:
    seed: int
    checkpoint: ValidationEpoch
    complete: bool

    def __post_init__(self):
        if (type(self.seed) is not int or self.seed not in (42, 43, 44)
                or type(self.checkpoint) is not ValidationEpoch or self.complete is not True):
            raise ValueError("complete validation-selected seed result required")


def _rank(scores, order):
    if not scores or not set(scores) <= set(order):
        raise ValueError("unknown/empty candidate set")
    maximum = max(v[0] for v in scores.values())
    eligible = [name for name, (f1, _) in scores.items() if maximum - f1 <= 1e-4]
    winner = min(eligible, key=lambda name: (scores[name][1], order.index(name)))
    return {"selected": winner, "exact_maximum": maximum,
            "selected_macro_f1": scores[winner][0], "scores": dict(scores)}


def select_screen(candidates, *, kind, eligible_initializations=None):
    if kind not in ("initialization", "objective"):
        raise ValueError("unknown screening phase")
    if kind == "initialization":
        if (not isinstance(eligible_initializations, (list, tuple))
                or not eligible_initializations
                or len(eligible_initializations) != len(set(eligible_initializations))
                or not set(eligible_initializations) <= set(INITIALIZATION_ORDER)):
            raise ValueError("declare all provenance-eligible initialization arms")
        required = set(eligible_initializations)
    else:
        if eligible_initializations is not None:
            raise ValueError("objective screens cannot override the frozen arm set")
        required = set(OBJECTIVE_ORDER)
    if set(candidates) != required:
        raise ValueError("all declared eligible screens required; no survivor selection")
    scores = {}
    for name, record in candidates.items():
        if type(record) is not SeedValidation or record.seed != 42:
            raise ValueError("screen requires complete seed42 records")
        scores[name] = (record.checkpoint.macro_f1, record.checkpoint.diagnostic_ce)
    return _rank(scores, INITIALIZATION_ORDER if kind == "initialization" else OBJECTIVE_ORDER)


def select_repeated_family(families):
    if len(families) != 2:
        raise ValueError("exactly nominated candidate and control required")
    scores = {}
    for name, records in families.items():
        records = list(records)
        if (len(records) != 3 or any(type(r) is not SeedValidation for r in records)
                or {r.seed for r in records} != {42, 43, 44}):
            raise ValueError("both families require all three complete seeds")
        scores[name] = (math.fsum(r.checkpoint.macro_f1 for r in records) / 3,
                        math.fsum(r.checkpoint.diagnostic_ce for r in records) / 3)
    return _rank(scores, OBJECTIVE_ORDER)

